unresolved: [
  {id: "U1", t: "Approve, amend or reject R-001 (Phase 2.5 re-baseline)", why: "Most research candidates depend on its components (benchmarks, universe, policy function, daily engine).", src: ["AR", "LOG"]},
  {id: "U2", t: "Base timeframe: hourly-on-5-minute (built, D-004/D-006) or daily (R-001)", why: "Decides the data, the engine, the laptop schedule and which strategies fit.", src: ["LOG", "AR"]},
  {id: "U3", t: "Research object: single-symbol grids (built) or universe hypotheses", why: "19% power at 972 variants; a breadth of one.", src: ["LOG", "AR"]},
  {id: "U4", t: "Validation gate: combined verdict with DSR (built) or staged verdicts with SPA/StepM", why: "The DSR answer ranges 0.20–0.76 with counting choices (D-024).", src: ["LOG", "AR"]},
  {id: "U5", t: "Sizing consistency between research and the risk gate", why: "A-001 #1: validated returns describe 100% exposure; the gate would allow about 20%.", src: ["LOG", "AR"]},
  {id: "U6", t: "Universe and survivorship source (U2 spike, paid data)", why: "Stock-level claims stay survivor-biased until this is resolved (spec §10.3).", src: ["AR", "SPEC"]},
  {id: "U7", t: "Risk policy numbers", why: "Every value in spec §7.1 is OPEN or PROPOSED.", src: ["SPEC"]},
  {id: "U8", t: "Where scanning sits, and who owns it", why: "No component exists; see gap G1.", src: []},
  {id: "U9", t: "How strategies are selected and combined at run time", why: "No allocator or selection rule is decided; see gap G2.", src: []},
  {id: "U10", t: "Merge PR #1 (Phase 2) and PR #2 (registry); approve R-002", why: "GitHub main has Phase 1 only; the registry lives on an unmerged branch.", src: ["PR1", "PR2"]},
  {id: "U11", t: "Event blackout as a default or as a tested challenger", why: "The spec plans it; R-001 says defer and measure.", src: ["SPEC", "AR"]},
  {id: "U12", t: "Paper broker behaviour: shorting (O-001), opening-auction fills (O-005)", why: "Determines the order types and whether short paper trading is meaningful.", src: ["LOG"]},
  {id: "U13", t: "Research store: Markdown registry or machine hypothesis registry", why: "A-003 'reconsider if'; R-001 step a.", src: ["LOGR", "AR"]},
  {id: "U14", t: "Real-money trading", why: "An explicit later decision (spec §7.4).", src: ["SPEC"]}
],

gaps: [
  {id: "G1", type: "Architectural gap", t: "No opportunity-detection stage",
   d: "The documented flow goes from 'approved strategy' straight to 'signals'. Eligibility (universe) is only proposed, and event hypotheses (E01, E07, E08) need event detection that no document assigns to a component. Timing strategies scan implicitly; event strategies cannot.", rel: ["scanner-gap", "universe-tiers", "event-detect"]},
  {id: "G2", type: "Architectural gap", t: "No runtime strategy-selection or allocation rule",
   d: "The spec caps each strategy at 20% and keeps per-strategy ledgers, but nothing decides which approved strategy is active in which situation or how capital is split. M03 and M09 are research only.", rel: ["select-gap", "regime-select", "portfolio-combo", "multi-strat"]},
  {id: "G3", type: "Unresolved dependency", t: "Two architectures coexist without a decision",
   d: "Phases 1–2 are built on the spec's design (hourly grid, single-symbol grids, combined verdict). R-001 proposes a different research object, timeframe and gate. Most research candidates depend on R-001 components (daily panel, benchmarks, universe, policy function).", rel: ["daily-base", "active-return", "policy-fn", "daily-engine"]},
  {id: "G4", type: "Contradiction", t: "Research sizing differs from trading sizing",
   d: "Known (A-001 #1). Every validated number today describes a position the gate would not allow.", rel: ["research-sizing", "risk-gate", "policy-fn"]},
  {id: "G5", type: "Overlap", t: "Several overlapping stores for ideas and evidence",
   d: "PROJECT_LOG, the Markdown registry (PR #2), STRATEGY_RESEARCH.md (unpushed docs branch), the spec's hypothesis queue and R-001's hypothesis registry all hold parts of the same research memory, on three different branches.", rel: ["idea-registry", "hyp-registry", "hyp-queue", "decision-log"]},
  {id: "G6", type: "Overlap", t: "Duplicate mechanisms for forward evidence and improvement",
   d: "Shadow lane (spec) vs forward record (R-001); champion–challenger (spec) vs forward-record challengers (R-001) vs M08/V09 drift detection; assurance checklist (built) vs validation contract V06.", rel: ["shadow", "forward-record", "champion", "adaptation", "verdict"]},
  {id: "G7", type: "Documented without purpose", t: "Methods outside the current scope or without a consumer",
   d: "E13 (crypto) and E14 (futures) are outside the decided scope (D-004, Alpaca equities). M04 multi-timeframe and V-4 entropy have no consuming strategy. They need a scope decision, not more research.", rel: ["e13", "e14", "mtf", "entropy"]},
  {id: "G8", type: "Missing component", t: "No cost, capacity or liquidity model beyond a flat 5 bp",
   d: "R-001 proposes an OHLC spread proxy; small-cap candidates (E05, E07, H-02) need capacity limits that no document specifies.", rel: ["vbt-engine", "e07", "h02"]},
  {id: "G9", type: "Inconsistency", t: "The spec says a signal combiner exists; the code has none",
   d: "Spec §8.4: 'The combiner interface exists from Phase 1'. src/trader/strategies has no combiner.", rel: ["combiner"]},
  {id: "G10", type: "Missing link", t: "No route from monitoring findings back to registered hypotheses",
   d: "Spec §8.2 feeds diagnostics into a hypothesis queue; nothing yet links registry IDs to experiments, trials or forward records.", rel: ["diagnostics", "idea-registry", "hyp-registry"]}
],

proposals: [
  {id: "P1", t: "Make scanning two explicit layers", d: "A shared, deterministic eligibility filter (the universe tier) and hypothesis-owned event or condition detectors. A scanner only narrows where an approved strategy looks; it never decides to trade, and it is versioned with the strategy. Order: universe → detectors → signals.", fix: ["G1"]},
  {id: "P2", t: "Treat strategy selection as a research decision", d: "Which strategies are active, and with what share of capital, is decided in the deployment step. Any situational switching (a regime filter) is part of a validated strategy version or of a portfolio allocator validated as its own hypothesis. No discretionary switching at run time.", fix: ["G2"]},
  {id: "P3", t: "Decide R-001 before adding research", d: "Resolve U1–U5 first; most candidates cannot be tested honestly without the benchmark layer, the universe and the policy function.", fix: ["G3", "G4"]},
  {id: "P4", t: "One path for research memory", d: "Markdown registry now → machine hypothesis registry after approval, with registry IDs as keys; STRATEGY_RESEARCH.md becomes an archive; merge the branches.", fix: ["G5", "G10"]},
  {id: "P5", t: "Pick one forward-evidence mechanism", d: "Choose the forward record or the shadow lane, and attach challengers and drift tests to it.", fix: ["G6"]},
  {id: "P6", t: "Check scope before research", d: "Park E13/E14 until the owner widens the scope; take methods without a consuming strategy off the active list.", fix: ["G7"]}
],

